import timeMAX_TRADES_PER_DAY = 6MAX_LOSS_STREAK = 3PAUSE_AFTER_LOSS = 1800  # 30 minstate = {    "trades_today": 0,    "loss_streak": 0,    "last_loss_time": 0}def can_trade():    # max trades    if state["trades_today"] >= MAX_TRADES_PER_DAY:        return False, "Daily trade limit reached"    # loss pause    if state["loss_streak"] >= MAX_LOSS_STREAK:        if time.time() - state["last_loss_time"] < PAUSE_AFTER_LOSS:            return False, "Paused due to loss streak"        # reset after pause        state["loss_streak"] = 0    return True, "OK"def register_trade(pnl):    state["trades_today"] += 1    if pnl < 0:        state["loss_streak"] += 1        state["last_loss_time"] = time.time()    else:        state["loss_streak"] = 0